function validateSchema(schema, row) {
  var errors = [];
  schema.columns.forEach(function(col) {
    var val = row[col.name];
    if (col.required && (val === null || val === undefined || val === '')) {
      errors.push(col.name + ' is required');
    } else if (val !== undefined && val !== null) {
      if (col.type === 'number' && typeof val !== 'number') errors.push(col.name + ' must be a number');
      if (col.type === 'string' && typeof val !== 'string') errors.push(col.name + ' must be a string');
      if (col.type === 'boolean' && typeof val !== 'boolean') errors.push(col.name + ' must be a boolean');
    }
  });
  return errors;
}

function createTransaction(initialState) {
  var original = JSON.parse(JSON.stringify(initialState));
  var current = JSON.parse(JSON.stringify(initialState));
  return {
    update: function(key, value) { current[key] = value; },
    commit: function() { original = JSON.parse(JSON.stringify(current)); return current; },
    rollback: function() { current = JSON.parse(JSON.stringify(original)); return original; }
  };
}
